import numpy as np

data = np.array([42000, 45000, 47000, 46000, 44000, 900000])

def mae(prediction, data):
    return np.mean(np.abs(data - prediction))

for candidate in [45000, 45500, 187333]:
    print(candidate, mae(candidate, data))
# the minimum mean absolute error occurs closest to 45500, the median
